#[global_allocator]
static GLOBAL_ALLOCATOR: CustomHeapAllocator = CustomHeapAllocator;

#[cfg(all(
    feature = "custom-heap",
    target_os = "solana",
    not(feature = "no-entrypoint")
))]
struct CustomHeapAllocator;

#[cfg(all(
    feature = "custom-heap",
    target_os = "solana",
    not(feature = "no-entrypoint")
))]
unsafe impl std::alloc::GlobalAlloc for CustomHeapAllocator {
    #[inline]
    unsafe fn alloc(&self, layout: std::alloc::Layout) -> *mut u8 {
        const EXTENDED_HEAP_BYTES: usize = 256 * 1024;

        let heap_start = anchor_lang::solana_program::entrypoint::HEAP_START_ADDRESS as usize;
        let default_heap_end = heap_start + anchor_lang::solana_program::entrypoint::HEAP_LENGTH;
        let extended_heap_end = heap_start + EXTENDED_HEAP_BYTES;
        let state_end = heap_start + std::mem::size_of::<usize>();
        let pos_ptr = heap_start as *mut usize;

        let current_pos = *pos_ptr;
        let pos = if current_pos == 0 {
            default_heap_end
        } else {
            current_pos
        };

        let floor = if pos > default_heap_end {
            default_heap_end
        } else {
            state_end
        };

        if let Some(next_pos) = allocate_from(pos, floor, layout) {
            *pos_ptr = next_pos;
            return next_pos as *mut u8;
        }

        if pos <= default_heap_end {
            if let Some(next_pos) = allocate_from(extended_heap_end, default_heap_end, layout) {
                *pos_ptr = next_pos;
                return next_pos as *mut u8;
            }
        }

        std::ptr::null_mut()
    }

    #[inline]
    unsafe fn dealloc(&self, _ptr: *mut u8, _layout: std::alloc::Layout) {}
}

#[cfg(all(
    feature = "custom-heap",
    target_os = "solana",
    not(feature = "no-entrypoint")
))]
#[inline]
fn allocate_from(pos: usize, floor: usize, layout: std::alloc::Layout) -> Option<usize> {
    let next_pos = pos.checked_sub(layout.size())? & !(layout.align().wrapping_sub(1));
    (next_pos >= floor).then_some(next_pos)
}

