#[event_cpi]
#[derive(Accounts)]
pub struct Settle<'info> {
    #[account(
        mut,
        seeds = [PA_STATE_SEED],
        bump = pa_state.bump,
        constraint = pa_state.schema_version == PAStateAccount::SCHEMA_VERSION
            @ PAError::UnsupportedStateSchema,
    )]
    pub pa_state: Account<'info, PAStateAccount>,

    #[account(mut)]
    pub payer: Signer<'info>,
    pub system_program: Program<'info, System>,

    /// CHECK: Validated at runtime against the root produced by this settlement.
    /// Cannot use a seeds constraint: the address depends on the resulting root,
    /// which is only known after commitments are appended.
    #[account(mut)]
    pub new_root_marker: UncheckedAccount<'info>,

    /// CHECK: Validated against verifier_router stored in PAStateAccount.
    #[account(constraint = verifier_router_program.key() == pa_state.verifier_router @ PAError::VerifierRouterFailed)]
    pub verifier_router_program: UncheckedAccount<'info>,

    /// CHECK: Router state PDA - validated by verifier_router during CPI.
    pub router: UncheckedAccount<'info>,

    /// CHECK: Verifier entry PDA - validated by verifier_router during CPI.
    pub verifier_entry: UncheckedAccount<'info>,

    /// CHECK: The groth16 verifier program - validated by verifier_router.
    pub verifier_program: UncheckedAccount<'info>,
}

