// Four separate event structs with identical fields: each produces a distinct Anchor
// discriminator (sha256 of the struct name), enabling indexers to filter by payload
// category at the log-parsing level without decoding the event body.
#[event]
pub struct ResourcePayloadEvent {
    pub tag: [u8; 32],
    pub index: u32,
    pub blob: Vec<u8>,
}

#[event]
pub struct DiscoveryPayloadEvent {
    pub tag: [u8; 32],
    pub index: u32,
    pub blob: Vec<u8>,
}

#[event]
pub struct ExternalPayloadEvent {
    pub tag: [u8; 32],
    pub index: u32,
    pub blob: Vec<u8>,
}

#[event]
pub struct ApplicationPayloadEvent {
    pub tag: [u8; 32],
    pub index: u32,
    pub blob: Vec<u8>,
}

/// Matches EVM PA's ActionExecuted event.
#[event]
pub struct ActionExecutedEvent {
    pub action_tree_root: [u8; 32],
    pub action_tag_count: u32,
}

/// Matches EVM PA's TransactionExecuted event, with each tag's role stated
/// explicitly: `is_consumed[i]` is true when `tags[i]` is a nullifier and
/// false when it is a commitment.
#[event]
pub struct TransactionExecutedEvent {
    pub tags: Vec<[u8; 32]>,
    pub logic_refs: Vec<[u8; 32]>,
    pub is_consumed: Vec<bool>,
}

/// Matches EVM PA's ForwarderCallExecuted event.
#[event]
pub struct ForwarderCallExecutedEvent {
    pub forwarder: Pubkey,
    pub input: Vec<u8>,
    pub output: Vec<u8>,
}

fn emit_app_data_events(
    events: &events::EventCpi,
    tag: &arm_core::Digest,
    app_data: &arm_core::logic_instance::AppData,
) -> Result<()> {
    let tag_bytes: [u8; 32] = (*tag).into();

    macro_rules! emit_payloads {
        ($payloads:expr, $Event:ident) => {
            for (i, payload) in $payloads.iter().enumerate() {
                if payload.deletion_criterion == DELETION_CRITERION_NEVER {
                    events.emit(&$Event {
                        tag: tag_bytes,
                        index: i as u32,
                        blob: arm_core::utils::words_to_bytes(&payload.blob).to_vec(),
                    })?;
                }
            }
        };
    }

    emit_payloads!(app_data.resource_payload, ResourcePayloadEvent);
    emit_payloads!(app_data.discovery_payload, DiscoveryPayloadEvent);
    emit_payloads!(app_data.external_payload, ExternalPayloadEvent);
    emit_payloads!(app_data.application_payload, ApplicationPayloadEvent);
    Ok(())
}
